18	package org.apache.solr.servlet;
19	
20	import static org.apache.solr.common.params.CommonParams.SOLR_REQUEST_CONTEXT_PARAM;
21	import static org.apache.solr.common.params.CommonParams.SOLR_REQUEST_TYPE_PARAM;
22	
23	import java.io.IOException;
24	import java.io.UncheckedIOException;
25	import java.lang.invoke.MethodHandles;
26	import java.util.HashMap;
27	import java.util.Map;
28	import java.util.concurrent.ConcurrentHashMap;
29	import javax.servlet.http.HttpServletRequest;
30	import net.jcip.annotations.ThreadSafe;
31	import org.apache.solr.client.solrj.SolrRequest;
32	import org.apache.solr.common.cloud.ClusterPropertiesListener;
33	import org.apache.solr.common.cloud.SolrZkClient;
34	import org.slf4j.Logger;
35	import org.slf4j.LoggerFactory;
36	
37	/**
38	 * This class is responsible for managing rate limiting per request type. Rate limiters can be
39	 * registered with this class against a corresponding type. There can be only one rate limiter
40	 * associated with a request type.
41	 *
42	 * <p>The actual rate limiting and the limits should be implemented in the corresponding
43	 * RequestRateLimiter implementation. RateLimitManager is responsible for the orchestration but not
44	 * the specifics of how the rate limiting is being done for a specific request type.
45	 */
46	@ThreadSafe
47	public class RateLimitManager implements ClusterPropertiesListener {
48	  private static final Logger log = LoggerFactory.getLogger(MethodHandles.lookup().lookupClass());
49	
50	  public static final String ERROR_MESSAGE =
51	      "Too many requests for this request type. Please try after some time or increase the quota for this request type";
52	  public static final int DEFAULT_CONCURRENT_REQUESTS =
53	      (Runtime.getRuntime().availableProcessors()) * 3;
54	  public static final long DEFAULT_SLOT_ACQUISITION_TIMEOUT_MS = -1;
55	  private final Map<String, RequestRateLimiter> requestRateLimiterMap;
56	
57	  private final Map<HttpServletRequest, RequestRateLimiter.SlotMetadata> activeRequestsMap;
58	
59	  public RateLimitManager() {
60	    this.requestRateLimiterMap = new HashMap<>();
61	    this.activeRequestsMap = new ConcurrentHashMap<>();
62	  }
63	
64	  @Override
65	  public boolean onChange(Map<String, Object> properties) {
66	
67	    // Hack: We only support query rate limiting for now
68	    QueryRateLimiter queryRateLimiter =
69	        (QueryRateLimiter) getRequestRateLimiter(SolrRequest.SolrRequestType.QUERY);
70	
71	    if (queryRateLimiter != null) {
72	      try {
73	        queryRateLimiter.processConfigChange(properties);
74	      } catch (IOException e) {
75	        throw new UncheckedIOException(e);
76	      }
77	    }
78	
79	    return false;
80	  }
81	
82	  // Handles an incoming request. The main orchestration code path, this method will
83	  // identify which (if any) rate limiter can handle this request. Internal requests will not be
84	  // rate limited
85	  // Returns true if request is accepted for processing, false if it should be rejected
86	  public boolean handleRequest(HttpServletRequest request) throws InterruptedException {
87	    String requestContext = request.getHeader(SOLR_REQUEST_CONTEXT_PARAM);
88	    String typeOfRequest = request.getHeader(SOLR_REQUEST_TYPE_PARAM);
89	
90	    if (typeOfRequest == null) {
91	      // Cannot determine if this request should be throttled
92	      return true;
93	    }
94	
95	    // Do not throttle internal requests
96	    if (requestContext != null
97	        && requestContext.equals(SolrRequest.SolrClientContext.SERVER.toString())) {
98	      return true;
99	    }
100	
101	    RequestRateLimiter requestRateLimiter = requestRateLimiterMap.get(typeOfRequest);
102	
103	    if (requestRateLimiter == null) {
104	      // No request rate limiter for this request type
105	      return true;
106	    }
107	
108	    RequestRateLimiter.SlotMetadata result = requestRateLimiter.handleRequest();
109	
110	    if (result != null) {
111	      // Can be the case if request rate limiter is disabled
112	      if (result.isReleasable()) {
113	        activeRequestsMap.put(request, result);
114	      }
115	      return true;
116	    }
117	
118	    RequestRateLimiter.SlotMetadata slotMetadata = trySlotBorrowing(typeOfRequest);
119	
120	    if (slotMetadata != null) {
121	      activeRequestsMap.put(request, slotMetadata);
122	      return true;
123	    }
124	
125	    return false;
126	  }
127	
128	  /* For a rejected request type, do the following:
129	   * For each request rate limiter whose type that is not of the type of the request which got rejected,
130	   * check if slot borrowing is enabled. If enabled, try to acquire a slot.
131	   * If allotted, return else try next request type.
132	   *
133	   * @lucene.experimental -- Can cause slots to be blocked if a request borrows a slot and is itself long lived.
134	   */
135	  private RequestRateLimiter.SlotMetadata trySlotBorrowing(String requestType) {
136	    for (Map.Entry<String, RequestRateLimiter> currentEntry : requestRateLimiterMap.entrySet()) {
137	      RequestRateLimiter.SlotMetadata result = null;
138	      RequestRateLimiter requestRateLimiter = currentEntry.getValue();
139	
140	      // Cant borrow from ourselves
141	      if (requestRateLimiter.getRateLimiterConfig().requestType.toString().equals(requestType)) {
142	        continue;
143	      }
144	
145	      if (requestRateLimiter.getRateLimiterConfig().isSlotBorrowingEnabled) {
146	        if (log.isWarnEnabled()) {
147	          String msg =
148	              "WARN: Experimental feature slots borrowing is enabled for request rate limiter type "
149	                  + requestRateLimiter.getRateLimiterConfig().requestType.toString();
150	
151	          log.warn(msg);
152	        }
153	
154	        try {
155	          result = requestRateLimiter.allowSlotBorrowing();
156	        } catch (InterruptedException e) {
157	          Thread.currentThread().interrupt();
158	        }
159	
160	        if (result == null) {
161	          throw new IllegalStateException("Returned metadata object is null");
162	        }
163	
164	        if (result.isReleasable()) {
165	          return result;
166	        }
167	      }
168	    }
169	
170	    return null;
171	  }
172	
173	  // Decrement the active requests in the rate limiter for the corresponding request type.
174	  public void decrementActiveRequests(HttpServletRequest request) {
175	    RequestRateLimiter.SlotMetadata slotMetadata = activeRequestsMap.get(request);
176	
177	    if (slotMetadata != null) {
178	      activeRequestsMap.remove(request);
179	      slotMetadata.decrementRequest();
180	    }
181	  }
182	
183	  public void registerRequestRateLimiter(
184	      RequestRateLimiter requestRateLimiter, SolrRequest.SolrRequestType requestType) {
185	    requestRateLimiterMap.put(requestType.toString(), requestRateLimiter);
186	  }
187	
188	  public RequestRateLimiter getRequestRateLimiter(SolrRequest.SolrRequestType requestType) {
189	    return requestRateLimiterMap.get(requestType.toString());
190	  }
191	
192	  public static class Builder {
193	    protected SolrZkClient solrZkClient;
194	
195	    public Bu
