18	package org.apache.solr.core;
19	
20	import static org.apache.solr.servlet.RateLimitManager.DEFAULT_CONCURRENT_REQUESTS;
21	import static org.apache.solr.servlet.RateLimitManager.DEFAULT_SLOT_ACQUISITION_TIMEOUT_MS;
22	
23	import org.apache.solr.client.solrj.SolrRequest;
24	
25	public class RateLimiterConfig {
26	  public static final String RL_CONFIG_KEY = "rate-limiters";
27	
28	  public SolrRequest.SolrRequestType requestType;
29	  public boolean isEnabled;
30	  public long waitForSlotAcquisition;
31	  public int allowedRequests;
32	  public boolean isSlotBorrowingEnabled;
33	  public int guaranteedSlotsThreshold;
34	
35	  public RateLimiterConfig(SolrRequest.SolrRequestType requestType) {
36	    this.requestType = requestType;
37	    this.isEnabled = false;
38	    this.allowedRequests = DEFAULT_CONCURRENT_REQUESTS;
39	    this.isSlotBorrowingEnabled = false;
40	    this.guaranteedSlotsThreshold = this.allowedRequests / 2;
41	    this.waitForSlotAcquisition = DEFAULT_SLOT_ACQUISITION_TIMEOUT_MS;
42	  }
43	
44	  public RateLimiterConfig(
45	      SolrRequest.SolrRequestType requestType,
46	      boolean isEnabled,
47	      int guaranteedSlotsThreshold,
48	      long waitForSlotAcquisition,
49	      int allowedRequests,
50	      boolean isSlotBorrowingEnabled) {
