28	/**
29	 * Handles rate limiting for a specific request type.
30	 *
31	 * <p>The control flow is as follows: Handle request -- Check if slot is available -- If available,
32	 * acquire slot and proceed -- else reject the same.
33	 */
34	@ThreadSafe
35	public class RequestRateLimiter {
36	
37	  // Total slots that are available for this request rate limiter.
38	  private final Semaphore totalSlotsPool;
39	
40	  // Competitive slots pool that are available for this rate limiter as well as borrowing by other
41	  // request rate limiters. By competitive, the meaning is that there is no prioritization for the
42	  // acquisition of these slots -- First Come First Serve, irrespective of whether the request is of
43	  // this request rate limiter or other.
44	  private final Semaphore borrowableSlotsPool;
45	
46	  private final AtomicInteger nativeReservations;
47	
48	  private final RateLimiterConfig rateLimiterConfig;
49	  public static final SlotReservation UNLIMITED =
50	      () -> {
51	        // no-op
52	      };
53	
54	  public RequestRateLimiter(RateLimiterConfig rateLimiterConfig) {
55	    this.rateLimiterConfig = rateLimiterConfig;
56	    totalSlotsPool = new Semaphore(rateLimiterConfig.allowedRequests);
57	    int guaranteedSlots = rateLimiterConfig.guaranteedSlotsThreshold;
58	    if (!rateLimiterConfig.isSlotBorrowingEnabled
59	        || guaranteedSlots >= rateLimiterConfig.allowedRequests) {
60	      // slot borrowing is disabled, either explicitly or implicitly
61	      borrowableSlotsPool = null;
62	      nativeReservations = null;
63	    } else if (guaranteedSlots <= 0) {
64	      // all slots are guaranteed
65	      borrowableSlotsPool = totalSlotsPool;
66	      nativeReservations = null;
67	    } else {
68	      borrowableSlotsPool = new Semaphore(rateLimiterConfig.allowedRequests - guaranteedSlots);
69	      nativeReservations = new AtomicInteger();
70	    }
71	  }
72	
73	  @VisibleForTesting
74	  boolean isEmpty() {
75	    if (totalSlotsPool.availablePermits() != rateLimiterConfig.allowedRequests) {
76	      return false;
77	    }
78	    if (nativeReservations == null) {
79	      return true;
80	    }
81	    if (nativeReservations.get() != 0) {
82	      return false;
83	    }
84	    assert borrowableSlotsPool != null; // implied by `nativeReservations != null`
85	    return borrowableSlotsPool.availablePermits()
86	        == rateLimiterConfig.allowedRequests - rateLimiterConfig.guaranteedSlotsThreshold;
87	  }
88	
89	  /**
90	   * Handles an incoming request. returns a metadata object representing the metadata for the
91	   * acquired slot, if acquired. If a slot is not acquired, returns a null metadata object.
92	   */
93	  public SlotReservation handleRequest() throws InterruptedException {
94	
95	    if (!rateLimiterConfig.isEnabled) {
96	      return UNLIMITED;
97	    }
98	
99	    if (totalSlotsPool.tryAcquire(
100	        rateLimiterConfig.waitForSlotAcquisition, TimeUnit.MILLISECONDS)) {
101	      if (nativeReservations == null) {
102	        assert borrowableSlotsPool == null || totalSlotsPool == borrowableSlotsPool;
103	        // simple case: all slots guaranteed; or none, do not double-acquire
104	        return new SingleSemaphoreReservation(totalSlotsPool);
105	      }
106	      assert borrowableSlotsPool != null; // implied by `nativeReservations != null`
107	      if (nativeReservations.incrementAndGet() <= rateLimiterConfig.guaranteedSlotsThreshold
108	          || borrowableSlotsPool.tryAcquire()) {
109	        // we either fungibly occupy a guaranteed slot, so don't have to acquire
110	        // a borrowable slot; or we acquire a borrowable slot
111	        return new NativeBorrowableReservation(
112	            totalSlotsPool,
113	            borrowableSlotsPool,
114	            nativeReservations,
115	            rateLimiterConfig.guaranteedSlotsThreshold);
116	      } else {
117	        // this should never happen, but if it does we should not leak permits/accounting
118	        nativeReservations.decrementAndGet();
119	        totalSlotsPool.release();
120	        throw new IllegalStateException(
121	            "if we have a top-level slot, there should be an available borrowable slot");
122	      }
123	    }
124	
125	    return null;
126	  }
127	
128	  /**
129	   * Whether to allow another request type to borrow a slot from this request rate limiter.
130	   * Typically works fine if there is a relatively lesser load on this request rate limiter's type
131	   * compared to the others (think of skew).
132	   *
133	   * @return returns a metadata object for the acquired slot, if acquired. If the slot was not
134	   *     acquired, returns a metadata object with a null pool.
135	   * @lucene.experimental -- Can cause slots to be blocked if a request borrows a slot and is itself
136	   *     long lived.
137	   */
138	  public SlotReservation allowSlotBorrowing() throws InterruptedException {
139	    if (borrowableSlotsPool == null) {
140	      return null;
141	    }
142	    // by the time we get to slot borrowing, we have already waited for the borrowing request-type's
143	    // max slot acquisition millis, so don't wait again. Borrow only if it's available immediately.
144	    if (totalSlotsPool.tryAcquire()) {
145	      if (totalSlotsPool == borrowableSlotsPool) {
146	        // simple case: there are no guaranteed slots; do not double-acquire
147	        return new SingleSemaphoreReservation(borrowableSlotsPool);
148	      } else if (borrowableSlotsPool.tryAcquire()) {
149	        return new BorrowedReservation(totalSlotsPool, borrowableSlotsPool);
150	      } else {
151	        // this can happen, e.g., if all of the borrowable slots are occupied
152	        // by non-native requests, but there are open guaranteed slots. In that
153	        // case, top-level acquire would succeed, but borrowed acquire would fail.
154	        totalSlotsPool.release();
155	      }
156	    }
157	
158	    return null;
159	  }
160	
161	  public RateLimiterConfig getRateLimiterConfig() {
162	    return rateLimiterConfig;
163	  }
164	
165	  public interface SlotReservation extends Closeable {}
166	
167	  // Represents the metadata for a slot
168	  static class SingleSemaphoreReservation implements SlotReservation {
169	    private final Semaphore usedPool;
170	
171	    public SingleSemaphoreReservation(Semaphore usedPool) {
172	      assert usedPool != null;
173	      this.usedPool = usedPool;
174	    }
175	
176	    @Override
177	    public void close() {
178	      usedPool.release();
179	    }
180	  }
181	
182	  static class NativeBorrowableReservation implements SlotReservation {
183	    private final Semaphore totalPool;
184	    private final Semaphore borrowablePool;
