18	package org.apache.solr.servlet;
19	
20	import static org.apache.solr.common.params.CommonParams.SOLR_REQUEST_CONTEXT_PARAM;
21	import static org.apache.solr.common.params.CommonParams.SOLR_REQUEST_TYPE_PARAM;
22	
23	import jakarta.servlet.http.HttpServletRequest;
24	import java.io.IOException;
25	import java.io.UncheckedIOException;
26	import java.lang.invoke.MethodHandles;
27	import java.util.Map;
28	import java.util.concurrent.ConcurrentHashMap;
29	import net.jcip.annotations.ThreadSafe;
30	import org.apache.solr.client.solrj.SolrRequest;
31	import org.apache.solr.cloud.ZkController;
32	import org.apache.solr.common.cloud.ClusterPropertiesListener;
33	import org.apache.solr.core.RateLimiterConfig;
34	import org.slf4j.Logger;
35	import org.slf4j.LoggerFactory;
36	
37	/**
38	 * This class is responsible for managing rate limiting per request type. Rate limiters can be
39	 * registered with this class against a corresponding type. There can be only one rate limiter
40	 * associated with a request type.
41	 *
42	 * <p>The actual rate limiting and the limits should be implemented in the corresponding
43	 * RequestRateLimiter implementation. RateLimitManager is responsible for the orchestration but not
44	 * the specifics of how the rate limiting is being done for a specific request type.
45	 */
46	@ThreadSafe
47	public class RateLimitManager implements ClusterPropertiesListener {
48	  private static final Logger log = LoggerFactory.getLogger(MethodHandles.lookup().lookupClass());
49	
50	  public static final String ERROR_MESSAGE =
51	      "Too many requests for this request type. Please try after some time or increase the quota for this request type";
52	  private final ConcurrentHashMap<String, RequestRateLimiter> requestRateLimiterMap;
53	
54	  public RateLimitManager() {
55	    this.requestRateLimiterMap = new ConcurrentHashMap<>();
56	  }
57	
58	  @Override
59	  public boolean onChange(Map<String, Object> properties) {
60	
61	    // Hack: We only support query rate limiting for now
62	    requestRateLimiterMap.compute(
63	        SolrRequest.SolrRequestType.QUERY.toString(),
64	        (k, v) -> {
65	          try {
66	            RateLimiterConfig newConfig =
67	                QueryRateLimiter.processConfigChange(
68	                    SolrRequest.SolrRequestType.QUERY,
69	                    v == null ? null : v.getRateLimiterConfig(),
70	                    properties);
71	            if (newConfig == null) {
72	              return v;
73	            } else {
74	              return new QueryRateLimiter(newConfig);
75	            }
76	          } catch (IOException e) {
77	            throw new UncheckedIOException(e);
78	          }
79	        });
80	
81	    return false;
82	  }
83	
84	  // Handles an incoming request. The main orchestration code path, this method will
85	  // identify which (if any) rate limiter can handle this request. Internal requests will not be
86	  // rate limited
87	  // Returns true if request is accepted for processing, false if it should be rejected
88	  public RequestRateLimiter.SlotReservation handleRequest(HttpServletRequest request)
89	      throws InterruptedException {
90	    String requestContext = request.getHeader(SOLR_REQUEST_CONTEXT_PARAM);
91	    String typeOfRequest = request.getHeader(SOLR_REQUEST_TYPE_PARAM);
92	
93	    if (typeOfRequest == null) {
94	      // Cannot determine if this request should be throttled
95	      return RequestRateLimiter.UNLIMITED;
96	    }
97	
98	    // Do not throttle internal requests
99	    if (requestContext != null
100	        && requestContext.equals(SolrRequest.SolrClientContext.SERVER.toString())) {
101	      return RequestRateLimiter.UNLIMITED;
102	    }
103	
104	    RequestRateLimiter requestRateLimiter = requestRateLimiterMap.get(typeOfRequest);
105	
106	    if (requestRateLimiter == null) {
107	      // No request rate limiter for this request type
108	      return RequestRateLimiter.UNLIMITED;
109	    }
110	
111	    // slot borrowing should be fallback behavior, so if `slotAcquisitionTimeoutInMS`
112	    // is configured it will be applied here (blocking if necessary), to make a best
113	    // effort to draw from the request's own slot pool.
114	    RequestRateLimiter.SlotReservation result = requestRateLimiter.handleRequest();
115	
116	    if (result != null) {
117	      return result;
118	    }
119	
120	    return trySlotBorrowing(typeOfRequest); // possibly null, if unable to borrow a slot
121	  }
122	
123	  /* For a rejected request type, do the following:
124	   * For each request rate limiter whose type that is not of the type of the request which got rejected,
125	   * check if slot borrowing is enabled. If enabled, try to acquire a slot.
126	   * If allotted, return else try next request type.
127	   *
128	   * @lucene.experimental -- Can cause slots to be blocked if a request borrows a slot and is itself long lived.
129	   */
130	  private RequestRateLimiter.SlotReservation trySlotBorrowing(String requestType) {
131	    // TODO: randomly distributed slot borrowing over available RequestRateLimiters
132	    for (Map.Entry<String, RequestRateLimiter> currentEntry : requestRateLimiterMap.entrySet()) {
133	      RequestRateLimiter.SlotReservation result = null;
134	      RequestRateLimiter requestRateLimiter = currentEntry.getValue();
135	
136	      // Cant borrow from ourselves
137	      if (requestRateLimiter.getRateLimiterConfig().requestType.toString().equals(requestType)) {
138	        continue;
139	      }
140	
141	      if (requestRateLimiter.getRateLimiterConfig().isSlotBorrowingEnabled) {
142	        if (log.isWarnEnabled()) {
143	          String msg =
144	              "WARN: Experimental feature slots borrowing is enabled for request rate limiter type "
145	                  + requestRateLimiter.getRateLimiterConfig().requestType.toString();
146	
147	          log.warn(msg);
148	        }
149	
150	        try {
151	          result = requestRateLimiter.allowSlotBorrowing();
152	        } catch (InterruptedException e) {
153	          Thread.currentThread().interrupt();
154	        }
155	
156	        if (result != null) {
157	          return result;
158	        }
159	      }
160	    }
161	
162	    return null;
163	  }
164	
165	  public void registerRequestRateLimiter(
166	      RequestRateLimiter requestRateLimiter, SolrRequest.SolrRequestType requestType) {
167	    requestRateLimiterMap.put(requestType.toString(), requestRateLimiter);
168	  }
169	
170	  public RequestRateLimiter getRequestRateLimiter(SolrRequest.SolrRequestType requestType) {
171	    return requestRateLimiterMap.get(requestType.toString());
172	  }
